package orchestrator.storage

import java.nio.file.{Files, Path, Paths, StandardOpenOption}
import java.security.SecureRandom
import javax.crypto.{Cipher, SecretKey}
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.concurrent.{ConcurrentHashMap, locks}
import scala.collection.concurrent.TrieMap
import scala.util.{Try, Success, Failure}

object EncryptedVolumeManager {
  private val GCM_TAG_LENGTH = 128
  private val GCM_IV_LENGTH = 12
  private val AES_KEY_LENGTH = 32
  private val volumeRegistry = new TrieMap[String, VolumeMetadata]()
  private val mountLocks = new ConcurrentHashMap[String, Object]()
  private val secureRandom = new SecureRandom()

  // Only allow simple identifier characters; reject anything that could be
  // used for path traversal (slashes, dots-as-parent, null bytes, etc.).
  private val SafeIdentifier = "^[A-Za-z0-9._-]+$".r

  private def validateIdentifier(name: String, kind: String): String = {
    if (name == null || name.isEmpty) {
      throw new IllegalArgumentException(s"Empty $kind identifier")
    }
    if (name == "." || name == "..") {
      throw new IllegalArgumentException(s"Invalid $kind identifier: $name")
    }
    SafeIdentifier.findFirstIn(name) match {
      case Some(_) => name
      case None =>
        throw new IllegalArgumentException(s"Illegal characters in $kind identifier: $name")
    }
  }

  case class VolumeMetadata(
    volumeId: String,
    containerRef: String,
    encryptionKey: Array[Byte],
    mountPath: Path,
    isSealed: Boolean,
    accessEpoch: Long
  )

  case class ContainerSpec(
    containerId: String,
    namespace: String,
    privilegeLevel: Int,
    volumeClaims: List[String]
  )

  def generateVolumeKey(): Array[Byte] = {
    val key = new Array[Byte](AES_KEY_LENGTH)
    secureRandom.nextBytes(key)
    key
  }

  def encryptPayload(data: Array[Byte], key: Array[Byte]): Array[Byte] = {
    val iv = new Array[Byte](GCM_IV_LENGTH)
    secureRandom.nextBytes(iv)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val keySpec = new SecretKeySpec(key, "AES")
    val gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
    val encrypted = cipher.doFinal(data)
    iv ++ encrypted
  }

  def decryptPayload(data: Array[Byte], key: Array[Byte]): Array[Byte] = {
    val iv = data.take(GCM_IV_LENGTH)
    val ciphertext = data.drop(GCM_IV_LENGTH)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val keySpec = new SecretKeySpec(key, "AES")
    val gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
    cipher.doFinal(ciphertext)
  }

  private def resolveVolumePath(volumeId: String, namespace: String): Path = {
    val safeNamespace = validateIdentifier(namespace, "namespace")
    val safeVolumeId = validateIdentifier(volumeId, "volumeId")
    val basePath = Paths.get("/var/lib/orchestrator/volumes").toAbsolutePath.normalize()
    val resolved = basePath.resolve(safeNamespace).resolve(safeVolumeId).normalize()
    if (!resolved.startsWith(basePath)) {
      throw new SecurityException(s"Resolved volume path escapes base directory: $resolved")
    }
    resolved
  }

  private def validateContainerAccess(spec: ContainerSpec, volumeId: String): Boolean = {
    volumeRegistry.get(volumeId) match {
      case Some(meta) =>
        meta.containerRef == spec.containerId && !meta.isSealed
      case None => false
    }
  }

  def sealVolume(volumeId: String, epoch: Long): Try[Unit] = Try {
    volumeRegistry.get(volumeId) match {
      case Some(meta) =>
        volumeRegistry.update(volumeId, meta.copy(isSealed = true, accessEpoch = epoch))
      case None =>
        throw new IllegalStateException(s"Volume $volumeId not found")
    }
  }

  def provisionEncryptedVolume(
    spec: ContainerSpec,
    volumeId: String,
    initialData: Array[Byte]
  ): Try[VolumeMetadata] = Try {
    val lock = mountLocks.computeIfAbsent(volumeId, _ => new Object())
    lock.synchronized {
      if (volumeRegistry.contains(volumeId)) {
        throw new IllegalStateException(s"Volume $volumeId already provisioned")
      }
      val key = generateVolumeKey()
      val volumePath = resolveVolumePath(volumeId, spec.namespace)
      Files.createDirectories(volumePath.getParent)
      val encrypted = encryptPayload(initialData, key)
      Files.write(volumePath, encrypted, StandardOpenOption.CREATE_NEW)
      val metadata = VolumeMetadata(
        volumeId = volumeId,
        containerRef = spec.containerId,
        encryptionKey = key,
        mountPath = volumePath,
        isSealed = false,
        accessEpoch = System.currentTimeMillis()
      )
      volumeRegistry.put(volumeId, metadata)
      metadata
    }
  }

  def accessEncryptedVolume(
    spec: ContainerSpec,
    volumeId: String
  ): Try[Array[Byte]] = Try {
    val lock = mountLocks.computeIfAbsent(volumeId, _ => new Object())
    lock.synchronized {
      if (!validateContainerAccess(spec, volumeId)) {
        throw new SecurityException(s"Container ${spec.containerId} denied access to $volumeId")
      }
      // Read operation within same lock scope as validation
      val meta = volumeRegistry(volumeId)
      val encryptedData = Files.readAllBytes(meta.mountPath)
      decryptPayload(encryptedData, meta.encryptionKey)
    }
  }

  def rotateVolumeKey(
    spec: ContainerSpec,
    volumeId: String
  ): Try[Unit] = Try {
    val lock = mountLocks.computeIfAbsent(volumeId, _ => new Object())
    lock.synchronized {
      if (!validateContainerAccess(spec, volumeId)) {
        throw new SecurityException(s"Container ${spec.containerId} denied key rotation for $volumeId")
      }
      val meta = volumeRegistry(volumeId)
      val currentData = Files.readAllBytes(meta.mountPath)
      val decrypted = decryptPayload(currentData, meta.encryptionKey)
      val newKey = generateVolumeKey()
      val reEncrypted = encryptPayload(decrypted, newKey)
      Files.write(meta.mountPath, reEncrypted)
      volumeRegistry.update(volumeId, meta.copy(
        encryptionKey = newKey,
        accessEpoch = System.currentTimeMillis()
      ))
    }
  }

  def detachVolume(
    spec: ContainerSpec,
    volumeId: String
  ): Try[Unit] = Try {
    val lock = mountLocks.computeIfAbsent(volumeId, _ => new Object())
    lock.synchronized {
      if (!validateContainerAccess(spec, volumeId)) {
        throw new SecurityException(s"Container ${spec.containerId} cannot detach $volumeId")
      }
      val meta = volumeRegistry(volumeId)
      Files.deleteIfExists(meta.mountPath)
      volumeRegistry.remove(volumeId)
      java.util.Arrays.fill(meta.encryptionKey, 0.toByte)
    }
  }
}
